export function abilityEditorPage(section,doc,key,rows,title,make,render){
 const view=doc.view??={},state=(view.abilityPages??={})[key]??={query:'',offset:0},bar=make('div'),search=make('input'),previous=make('button','이전'),next=make('button','다음'),count=make('output');bar.className='form-section-heading';bar.dataset.abilityPage=key;search.type='search';search.placeholder='검색';search.value=state.query;search.setAttribute('aria-label',(key==='attributes'?'속성':'시작 능력')+' 검색');
 const indices=[];for(let i=0;i<rows.length;i++)if(title(rows[i]).toLocaleLowerCase().includes(state.query.toLocaleLowerCase()))indices.push(i);state.offset=Math.floor(Math.max(0,Math.min(state.offset,Math.max(0,indices.length-1)))/25)*25;previous.disabled=state.offset===0;next.disabled=state.offset+25>=indices.length;count.textContent=(indices.length?state.offset+1:0)+'–'+Math.min(indices.length,state.offset+25)+' / '+indices.length;
 search.onchange=()=>{state.query=search.value;state.offset=0;render();};previous.onclick=()=>{state.offset-=25;render();};next.onclick=()=>{state.offset+=25;render();};bar.append(search,previous,count,next);section.append(bar);return indices.slice(state.offset,state.offset+25).map(index=>({row:rows[index],index}));
}
